window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-a31ca4c18bec47b6"]={"versions": [{"id": "FIG-a31ca4c18bec47b6", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm (Ausschnitt aus dem AUTOSAR-Metamodell, M2-Ebene, <em>System Template</em> / FIBEX-Mapping).</li>\n<li><strong>Funktionaler Kontext:</strong> Modellierung globaler Zeitdomänen (<em>Global Time Synchronization</em>) für Ethernet im Rahmen des BSW-Stacks (Zusammenwirken von <code>StbM</code> – <em>Synchronized Time-Base Manager</em> und <code>EthTSyn</code> – <em>Time Synchronization over Ethernet</em>).</li>\n<li><strong>Zweck:</strong> Bereitstellung deklarativer Konfigurationsdaten in der Systembeschreibung (ARXML) zur Definition zeitsynchroner Netzwerke über Ethernet (gPTP nach IEEE 802.1AS bzw. AUTOSAR-Erweiterungen), inklusive Domänenhierarchien, Überwachungszeiträumen und absichernder Data-IDs.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>GlobalTime::GlobalTimeDomain</code></strong> (Spezialisierung von <code>FibexElement</code>):</li>\n<li>Repräsentiert eine logische Zeitsynchronisationsdomäne im Gesamtsystem.</li>\n<li><em>Attribute:</em></li>\n<li><code>domainId :PositiveInteger</code> [1..1]: Eindeutige Kennung der Zeitbasis (korrespondiert mit der gPTP-<code>domainNumber</code> und der <code>StbM</code>-Time-Base-ID).</li>\n<li><code>debounceTime :TimeValue</code> [0..1]: Mindestabstand zur Ratenbegrenzung bzw. Entprellung von Statusänderungen oder Sync-Meldungen.</li>\n<li><code>syncLossThreshold :TimeValue</code> [0..1]: Maximal tolerierte Zeitdifferenz zur Master-Zeit vor Kennzeichnung des Synchronisationsverlusts.</li>\n<li><code>syncLossTimeout :TimeValue</code> [0..1]: Zeitspanne ohne gültige Synchronisationsnachricht, nach deren Ablauf der Verlust der Zeitbasis deklariert wird.</li>\n<li><em>Assoziationen / Relationen:</em></li>\n<li><code>+offsetTimeDomain</code> [0..1]: Unidirektionale Selbstassoziation zur Referenzierung einer Basis-Zeitdomäne, aus der diese Domäne über einen statischen/dynamischen Offset abgeleitet wird.</li>\n<li><code>+subDomain</code> [0..*]: Unidirektionale 1:n-Selbstassoziation zur hierarchischen Kaskadierung untergeordneter Zeitdomänen (z. B. Gatewaying über mehrere Bussegmente).</li>\n<li><code>+globalTimeDomainProps</code> [0..1]: Komposition auf <code>AbstractGlobalTimeDomainProps</code>.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong><code>GlobalTime::AbstractGlobalTimeDomainProps</code></strong> (abstrakte Basisklasse):</li>\n<li>Kapselt busspezifische Eigenschaften einer Zeitdomäne (für CAN, FlexRay, Ethernet) polymorph unterhalb der generischen <code>GlobalTimeDomain</code>.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong><code>EthGlobalTimeDomainProps</code></strong> (Spezialisierung von <code>AbstractGlobalTimeDomainProps</code>):</li>\n<li>Konkrete Implementierung für Ethernet-basierte Zeitdomänen.</li>\n<li><em>Attribute:</em></li>\n<li><code>fupDataIDList :PositiveInteger</code> [0..16] <code>{ordered}</code>: Geordnete Sequenz von bis zu 16 Data-IDs zur kryptografischen/integritätsbezogenen Absicherung von <em>Follow_Up</em> (FUP)-Nachrichten gegen Replay-Angriffe.</li>\n<li><code>messageCompliance :EthGlobalTimeMessageFormatEnum</code> [1..1]: Selektor für das PTP-Nachrichtenformat.</li>\n<li><code>vlanPriority :PositiveInteger</code> [0..1]: Priority Code Point (PCP nach IEEE 802.1Q, Wertebereich 0..7) für den Ethernet-VLAN-Tag zur priorisierten Weiterleitung in Switches/Endknoten.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong><code>«enumeration» EthGlobalTimeMessageFormatEnum</code></strong>:</li>\n<li><code>IEEE802_1AS</code>: Standardkonforme gPTP-Nachrichten gemäß IEEE 802.1AS.</li>\n<li><code>IEEE802_1AS_AUTOSAR</code>: AUTOSAR-spezifisches Subprofil mit erweiterten TLVs (z. B. für AUTOSAR-spezifisches Time-Gatewaying, Status-Bits und CRC-gesicherte Nutzdaten).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf (falls zutreffend)</h4>\n<p class=\"fig-p\">Das statische Metamodell definiert die Parameter für folgende Laufzeitabläufe im <code>EthTSyn</code>- und <code>StbM</code>-Stack:</p>\n<ol class=\"fig-list\">\n<li><strong>Nachrichtenvalidierung & Sequence-Tracking:</strong> Bei Wahl von <code>IEEE802_1AS_AUTOSAR</code> wird beim Empfang einer <em>Follow_Up</em>-PDU die geordnete <code>fupDataIDList</code> zur Integritäts- und Sequence-Counter-Prüfung verwendet. Entspricht die berechnete Prüfsumme/Data-ID nicht dem erwarteten Sequenzwert der Liste, wird der Timestamp verworfen.</li>\n<li><strong>Synchronisationsüberwachung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ein Timer überwacht das Intervall empfangener Sync-Frames gegen <code>syncLossTimeout</code>.</li>\n<li>Weicht der rekonstruierte Offset vom Master über <code>syncLossThreshold</code> ab oder läuft der Timeout ab, meldet <code>StbM</code> via <code>Dem</code> / <code>Det</code> einen Sync-Verlust (<code>TIMEOUT</code> / <code>SYNC_LOSS</code>) an die Diagnose und setzt den Time-Base-Status auf <em>UNSYNC</em>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Entprellung:</strong> Zustandsübergänge zwischen synchronisiertem und unsynchronisiertem Status werden über <code>debounceTime</code> zeitlich gefiltert, um Hystereseeffekte im BSW-Status zu unterdrücken.</li>\n</ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konfigurationsableitung (ECU Configuration):</strong></li>\n<li>Parameter aus <code>EthGlobalTimeDomainProps</code> transformieren im BSW-Generator direkt in die Konfigurationscontainer <code>EthTSynGlobalTimeDomain</code> (<code>EthTSynGlobalTimeFollowUpDataIDList</code>, <code>EthTSynFramePriority</code>, <code>EthTSynMessageCompliance</code>).</li>\n<li><code>domainId</code> bindet die Konfiguration im <code>StbM</code> (<code>StbMSynchronizedTimeBase</code> / <code>StbMTimeBaseId</code>).</li>\n<li><strong>Implementierungsrestriktionen:</strong></li>\n<li><code>{ordered}</code> auf <code>fupDataIDList</code>: Die XML-Serialisierungsreihenfolge im ARXML ist semantisch bindend; Index-Verwechslungen führen zu CRC-Fehlern und sofortigem Synchronisationsabbruch im <code>EthTSyn</code>.</li>\n<li><code>vlanPriority</code>: Bei gesetztem Parameter muss der zugrundeliegende Ethernet-Interface-Stack (<code>EthIf</code>) zwingend mit VLAN-Support und korrespondierender PCP-Priorisierung konfiguriert sein.</li>\n<li><code>offsetTimeDomain</code>: Erfordert im <code>StbM</code> eine Offset-Zeitbasis (<code>StbMOffsetTimeBase</code>). Es darf kein eigenständiger PTP-Master für diese Domain konfiguriert werden; die Synchronisation erfolgt rechnerisch rein intern via Offset-Addition zur referenzierten Master-Domäne.</li>\n</ul>"}, {"id": "FIG-cf83a50615172ed9", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm (Ausschnitt aus dem AUTOSAR-Metamodell, M2-Ebene, <em>System Template</em> / FIBEX-Mapping).</li>\n<li><strong>Funktionaler Kontext:</strong> Modellierung globaler Zeitdomänen (<em>Global Time Synchronization</em>) für Ethernet im Rahmen des BSW-Stacks (Zusammenwirken von <code>StbM</code> – <em>Synchronized Time-Base Manager</em> und <code>EthTSyn</code> – <em>Time Synchronization over Ethernet</em>).</li>\n<li><strong>Zweck:</strong> Bereitstellung deklarativer Konfigurationsdaten in der Systembeschreibung (ARXML) zur Definition zeitsynchroner Netzwerke über Ethernet (gPTP nach IEEE 802.1AS bzw. AUTOSAR-Erweiterungen), inklusive Domänenhierarchien, Überwachungszeiträumen und absichernder Data-IDs.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>GlobalTime::GlobalTimeDomain</code></strong> (Spezialisierung von <code>FibexElement</code>):</li>\n<li>Repräsentiert eine logische Zeitsynchronisationsdomäne im Gesamtsystem.</li>\n<li><em>Attribute:</em></li>\n<li><code>domainId :PositiveInteger</code> [1..1]: Eindeutige Kennung der Zeitbasis.</li>\n<li><code>debounceTime :TimeValue</code> [0..1]: Mindestabstand zur Ratenbegrenzung bzw. Entprellung von Statusänderungen oder Sync-Meldungen.</li>\n<li><code>syncLossTimeout :TimeValue</code> [0..1]: Zeitspanne ohne gültige Synchronisationsnachricht, nach deren Ablauf der Verlust der Zeitbasis deklariert wird.</li>\n<li><em>Assoziationen / Relationen:</em></li>\n<li><code>+offsetTimeDomain</code> [0..1]: Unidirektionale Selbstassoziation zur Referenzierung einer Basis-Zeitdomäne.</li>\n<li><code>+globalTimeSubDomain</code> [0..*]: Unidirektionale Kaskadierung untergeordneter Zeitdomänen mit Stereotyp <code>«atpVariation»</code>.</li>\n<li><code>+globalTimeDomainProperty</code> [0..1]: Komposition auf <code>AbstractGlobalTimeDomainProps</code> mit Stereotyp <code>«atpVariation»</code>.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong><code>GlobalTime::AbstractGlobalTimeDomainProps</code></strong> (abstrakte Basisklasse):</li>\n<li>Kapselt busspezifische Eigenschaften einer Zeitdomäne polymorph unterhalb von <code>GlobalTimeDomain</code>.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong><code>EthGlobalTimeDomainProps</code></strong> (Spezialisierung von <code>AbstractGlobalTimeDomainProps</code>):</li>\n<li>Konkrete Eigenschaftsklasse für Ethernet-basierte Zeitdomänen.</li>\n<li><em>Attribute:</em></li>\n<li><code>destinationPhysicalAddress :MacAddressString</code> [0..1]: Physikalische Ziel-MAC-Adresse für Ethernet-Zeitsynchronisationsnachrichten.</li>\n<li><code>fupDataIDList :PositiveInteger</code> [0..16] <code>{ordered}</code>: Geordnete Sequenz von bis zu 16 Data-IDs zur Absicherung von <em>Follow_Up</em>-Nachrichten.</li>\n<li><code>messageCompliance :EthGlobalTimeMessageFormatEnum</code> [1..1]: Selektor für das PTP-Nachrichtenformat.</li>\n<li><code>vlanPriority :PositiveInteger</code> [0..1]: Priority Code Point (PCP nach IEEE 802.1Q) für das VLAN-Tagging.</li>\n<li><em>Assoziationen / Relationen:</em></li>\n<li><code>+crcFlags</code> [0..1]: Komposition auf <code>EthTSynCrcFlags</code>.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong><code>EthTSynCrcFlags</code></strong>:</li>\n<li>Konfiguriert die Einbeziehung einzelner Header-Felder in die Prüfsummenberechnung (CRC) für Time-Synchronization-Nachrichten über Ethernet.</li>\n<li><em>Attribute:</em></li>\n<li><code>crcCorrectionField :Boolean</code> [0..1]: Berücksichtigung des Correction-Field in der CRC.</li>\n<li><code>crcDomainNumber :Boolean</code> [0..1]: Berücksichtigung der Domain-Nummer in der CRC.</li>\n<li><code>crcMessageLength :Boolean</code> [0..1]: Berücksichtigung der Nachrichtenlänge in der CRC.</li>\n<li><code>crcPreciseOriginTimestamp :Boolean</code> [0..1]: Berücksichtigung des Precise-Origin-Timestamps in der CRC.</li>\n<li><code>crcSequenceId :Boolean</code> [0..1]: Berücksichtigung der Sequence-ID in der CRC.</li>\n<li><code>crcSourcePortIdentity :Boolean</code> [0..1]: Berücksichtigung der Source-Port-Identity in der CRC.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong><code>«enumeration» EthGlobalTimeMessageFormatEnum</code></strong>:</li>\n<li><code>IEEE802_1AS</code>: Standardkonforme gPTP-Nachrichten gemäß IEEE 802.1AS.</li>\n<li><code>IEEE802_1AS_AUTOSAR</code>: AUTOSAR-spezifisches Subprofil mit erweiterten TLVs und Absicherungsmechanismen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das statische Metamodell definiert die Parameter für folgende Laufzeitabläufe im <code>EthTSyn</code>- und <code>StbM</code>-Stack:</p>\n<ol class=\"fig-list\">\n<li><strong>Nachrichtenvalidierung & Sequence-Tracking:</strong> Bei Wahl von <code>IEEE802_1AS_AUTOSAR</code> wird beim Empfang einer <em>Follow_Up</em>-PDU die geordnete <code>fupDataIDList</code> zur Integritäts- und Sequence-Counter-Prüfung verwendet. Entspricht die berechnete Prüfsumme/Data-ID nicht dem erwarteten Sequenzwert der Liste, wird der Timestamp verworfen.</li>\n<li><strong>Synchronisationsüberwachung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ein Timer überwacht das Intervall empfangener Sync-Frames gegen <code>syncLossTimeout</code>.</li>\n<li>Weicht der rekonstruierte Offset vom Master über <code>syncLossThreshold</code> ab oder läuft der Timeout ab, meldet <code>StbM</code> via <code>Dem</code> / <code>Det</code> einen Sync-Verlust (<code>TIMEOUT</code> / <code>SYNC_LOSS</code>) an die Diagnose und setzt den Time-Base-Status auf <em>UNSYNC</em>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Entprellung:</strong> Zustandsübergänge zwischen synchronisiertem und unsynchronisiertem Status werden über <code>debounceTime</code> zeitlich gefiltert, um Hystereseeffekte im BSW-Status zu unterdrücken.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Architektur- und Stack-Abbildung:</strong> Die Eigenschaften steuern direkt die Module <code>EthTSyn</code> und <code>StbM</code>. Über <code>destinationPhysicalAddress</code> wird festgelegt, ob Unicast- oder Multicast-MACs für gPTP verwendet werden.</li>\n<li><strong>Integritätsschutz:</strong> Über <code>EthTSynCrcFlags</code> lässt sich granular konfigurieren, welche Bestandteile der Ethernet-Zeitsynchronisationsnachrichten durch Prüfsummen abgesichert werden, passend zu den AUTOSAR-Erweiterungen (<code>IEEE802_1AS_AUTOSAR</code>).</li>\n<li><strong>Variantenbildung:</strong> Durch den Stereotyp <code>«atpVariation»</code> an <code>+globalTimeSubDomain</code> und <code>+globalTimeDomainProperty</code> können Subdomänen und busspezifische Eigenschaften post-build oder über Bindungszeitpunkte variiert werden.</li>\n</ul>"}, {"id": "FIG-bae6585e530974b4", "releases": ["R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm (Ausschnitt aus dem AUTOSAR-Metamodell, M2-Ebene, <em>System Template</em> / FIBEX-Mapping).</li>\n<li><strong>Funktionaler Kontext:</strong> Modellierung globaler Zeitdomänen (<em>Global Time Synchronization</em>) für Ethernet im Rahmen des BSW-Stacks (Zusammenwirken von <code>StbM</code> – <em>Synchronized Time-Base Manager</em> und <code>EthTSyn</code> – <em>Time Synchronization over Ethernet</em>).</li>\n<li><strong>Zweck:</strong> Bereitstellung deklarativer Konfigurationsdaten in der Systembeschreibung (ARXML) zur Definition zeitsynchroner Netzwerke über Ethernet (gPTP nach IEEE 802.1AS bzw. AUTOSAR-Erweiterungen), inklusive Domänenhierarchien, Überwachungszeiträumen und absichernder Data-IDs.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>GlobalTime::GlobalTimeDomain</code></strong> (Spezialisierung von <code>FibexElement</code>):</li>\n<li>Repräsentiert eine logische Zeitsynchronisationsdomäne im Gesamtsystem.</li>\n<li><em>Attribute:</em></li>\n<li><code>domainId :PositiveInteger</code> [1..1]: Eindeutige Kennung der Zeitbasis.</li>\n<li><code>debounceTime :TimeValue</code> [0..1]: Mindestabstand zur Ratenbegrenzung bzw. Entprellung von Statusänderungen oder Sync-Meldungen.</li>\n<li><code>syncLossTimeout :TimeValue</code> [0..1]: Zeitspanne ohne gültige Synchronisationsnachricht, nach deren Ablauf der Verlust der Zeitbasis deklariert wird.</li>\n<li><em>Assoziationen / Relationen:</em></li>\n<li><code>+offsetTimeDomain</code> [0..1]: Unidirektionale Selbstassoziation zur Referenzierung einer Basis-Zeitdomäne.</li>\n<li><code>+globalTimeSubDomain</code> [0..*]: Unidirektionale Kaskadierung untergeordneter Zeitdomänen mit Stereotyp <code>«atpVariation»</code>.</li>\n<li><code>+globalTimeDomainProperty</code> [0..1]: Komposition auf <code>AbstractGlobalTimeDomainProps</code> mit Stereotyp <code>«atpVariation»</code>.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong><code>GlobalTime::AbstractGlobalTimeDomainProps</code></strong> (abstrakte Basisklasse):</li>\n<li>Kapselt busspezifische Eigenschaften einer Zeitdomäne polymorph unterhalb von <code>GlobalTimeDomain</code>.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong><code>EthGlobalTimeDomainProps</code></strong> (Spezialisierung von <code>AbstractGlobalTimeDomainProps</code>):</li>\n<li>Konkrete Eigenschaftsklasse für Ethernet-basierte Zeitdomänen.</li>\n<li><em>Attribute:</em></li>\n<li><code>destinationPhysicalAddress :MacAddressString</code> [0..1]: Physikalische Ziel-MAC-Adresse für Ethernet-Zeitsynchronisationsnachrichten.</li>\n<li><code>fupDataIDList :PositiveInteger</code> [0..16] <code>{ordered}</code>: Geordnete Sequenz von bis zu 16 Data-IDs zur Absicherung von <em>Follow_Up</em>-Nachrichten.</li>\n<li><code>messageCompliance :EthGlobalTimeMessageFormatEnum</code> [1..1]: Selektor für das PTP-Nachrichtenformat.</li>\n<li><code>vlanPriority :PositiveInteger</code> [0..1]: Priority Code Point (PCP nach IEEE 802.1Q) für das VLAN-Tagging.</li>\n<li><em>Assoziationen / Relationen:</em></li>\n<li><code>+crcFlags</code> [0..1]: Komposition auf <code>EthTSynCrcFlags</code>.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong><code>EthTSynCrcFlags</code></strong>:</li>\n<li>Konfiguriert die Einbeziehung einzelner Header-Felder in die Prüfsummenberechnung (CRC) für Time-Synchronization-Nachrichten über Ethernet.</li>\n<li><em>Attribute:</em></li>\n<li><code>crcCorrectionField :Boolean</code> [0..1]: Berücksichtigung des Correction-Field in der CRC.</li>\n<li><code>crcDomainNumber :Boolean</code> [0..1]: Berücksichtigung der Domain-Nummer in der CRC.</li>\n<li><code>crcMessageLength :Boolean</code> [0..1]: Berücksichtigung der Nachrichtenlänge in der CRC.</li>\n<li><code>crcPreciseOriginTimestamp :Boolean</code> [0..1]: Berücksichtigung des Precise-Origin-Timestamps in der CRC.</li>\n<li><code>crcSequenceId :Boolean</code> [0..1]: Berücksichtigung der Sequence-ID in der CRC.</li>\n<li><code>crcSourcePortIdentity :Boolean</code> [0..1]: Berücksichtigung der Source-Port-Identity in der CRC.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong><code>«enumeration» EthGlobalTimeMessageFormatEnum</code></strong>:</li>\n<li><code>IEEE802_1AS</code>: Standardkonforme gPTP-Nachrichten gemäß IEEE 802.1AS.</li>\n<li><code>IEEE802_1AS_AUTOSAR</code>: AUTOSAR-spezifisches Subprofil mit erweiterten TLVs und Absicherungsmechanismen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das statische Metamodell definiert die Parameter für folgende Laufzeitabläufe im <code>EthTSyn</code>- und <code>StbM</code>-Stack:</p>\n<ol class=\"fig-list\">\n<li><strong>Nachrichtenvalidierung & Sequence-Tracking:</strong> Bei Wahl von <code>IEEE802_1AS_AUTOSAR</code> wird beim Empfang einer <em>Follow_Up</em>-PDU die geordnete <code>fupDataIDList</code> zur Integritäts- und Sequence-Counter-Prüfung verwendet. Entspricht die berechnete Prüfsumme/Data-ID nicht dem erwarteten Sequenzwert der Liste, wird der Timestamp verworfen.</li>\n<li><strong>Synchronisationsüberwachung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ein Timer überwacht das Intervall empfangener Sync-Frames gegen <code>syncLossTimeout</code>.</li>\n<li>Weicht der rekonstruierte Offset vom Master über <code>syncLossThreshold</code> ab oder läuft der Timeout ab, meldet <code>StbM</code> via <code>Dem</code> / <code>Det</code> einen Sync-Verlust (<code>TIMEOUT</code> / <code>SYNC_LOSS</code>) an die Diagnose und setzt den Time-Base-Status auf <em>UNSYNC</em>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Entprellung:</strong> Zustandsübergänge zwischen synchronisiertem und unsynchronisiertem Status werden über <code>debounceTime</code> zeitlich gefiltert, um Hystereseeffekte im BSW-Status zu unterdrücken.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Architektur- und Stack-Abbildung:</strong> Die Eigenschaften steuern direkt die Module <code>EthTSyn</code> und <code>StbM</code>. Über <code>destinationPhysicalAddress</code> wird festgelegt, ob Unicast- oder Multicast-MACs für gPTP verwendet werden.</li>\n<li><strong>Integritätsschutz:</strong> Über <code>EthTSynCrcFlags</code> lässt sich granular konfigurieren, welche Bestandteile der Ethernet-Zeitsynchronisationsnachrichten durch Prüfsummen abgesichert werden, passend zu den AUTOSAR-Erweiterungen (<code>IEEE802_1AS_AUTOSAR</code>).</li>\n<li><strong>Variantenbildung:</strong> Durch den Stereotyp <code>«atpVariation»</code> an <code>+globalTimeSubDomain</code> und <code>+globalTimeDomainProperty</code> können Subdomänen und busspezifische Eigenschaften post-build oder über Bindungszeitpunkte variiert werden.</li>\n</ul>"}, {"id": "FIG-b1175ffbdbe95c07", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm (Ausschnitt aus dem AUTOSAR-Metamodell, M2-Ebene, <em>System Template</em> / FIBEX-Mapping).</li>\n<li><strong>Funktionaler Kontext:</strong> Modellierung globaler Zeitdomänen (<em>Global Time Synchronization</em>) für Ethernet im Rahmen des BSW-Stacks (Zusammenwirken von <code>StbM</code> – <em>Synchronized Time-Base Manager</em> und <code>EthTSyn</code> – <em>Time Synchronization over Ethernet</em>).</li>\n<li><strong>Zweck:</strong> Bereitstellung deklarativer Konfigurationsdaten in der Systembeschreibung (ARXML) zur Definition zeitsynchroner Netzwerke über Ethernet (gPTP nach IEEE 802.1AS bzw. AUTOSAR-Erweiterungen), inklusive Domänenhierarchien, Überwachungszeiträumen und absichernder Data-IDs.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>GlobalTime::GlobalTimeDomain</code></strong> (Spezialisierung von <code>FibexElement</code>):</li>\n<li>Repräsentiert eine logische Zeitsynchronisationsdomäne im Gesamtsystem.</li>\n<li><em>Attribute:</em></li>\n<li><code>domainId :PositiveInteger</code> [1..1]: Eindeutige Kennung der Zeitbasis.</li>\n<li><code>debounceTime :TimeValue</code> [0..1]: Mindestabstand zur Ratenbegrenzung bzw. Entprellung von Statusänderungen oder Sync-Meldungen.</li>\n<li><code>syncLossTimeout :TimeValue</code> [0..1]: Zeitspanne ohne gültige Synchronisationsnachricht, nach deren Ablauf der Verlust der Zeitbasis deklariert wird.</li>\n<li><em>Assoziationen / Relationen:</em></li>\n<li><code>+offsetTimeDomain</code> [0..1]: Unidirektionale Selbstassoziation zur Referenzierung einer Basis-Zeitdomäne.</li>\n<li><code>+globalTimeSubDomain</code> [0..*]: Unidirektionale Kaskadierung untergeordneter Zeitdomänen mit Stereotyp <code>«atpVariation,atpSplitable»</code>.</li>\n<li><code>+globalTimeDomainProperty</code> [0..1]: Komposition auf <code>AbstractGlobalTimeDomainProps</code> mit Stereotyp <code>«atpVariation,atpSplitable»</code>.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong><code>GlobalTime::AbstractGlobalTimeDomainProps</code></strong> (abstrakte Basisklasse):</li>\n<li>Kapselt busspezifische Eigenschaften einer Zeitdomäne polymorph unterhalb von <code>GlobalTimeDomain</code>.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong><code>EthGlobalTimeDomainProps</code></strong> (Spezialisierung von <code>AbstractGlobalTimeDomainProps</code>):</li>\n<li>Konkrete Eigenschaftsklasse für Ethernet-basierte Zeitdomänen.</li>\n<li><em>Attribute:</em></li>\n<li><code>destinationPhysicalAddress :MacAddressString</code> [0..1]: Physikalische Ziel-MAC-Adresse für Ethernet-Zeitsynchronisationsnachrichten.</li>\n<li><code>fupDataIDList :PositiveInteger</code> [0..16] <code>{ordered}</code>: Geordnete Sequenz von bis zu 16 Data-IDs zur Absicherung von <em>Follow_Up</em>-Nachrichten.</li>\n<li><code>messageCompliance :EthGlobalTimeMessageFormatEnum</code> [1..1]: Selektor für das PTP-Nachrichtenformat.</li>\n<li><code>vlanPriority :PositiveInteger</code> [0..1]: Priority Code Point (PCP nach IEEE 802.1Q) für das VLAN-Tagging.</li>\n<li><em>Assoziationen / Relationen:</em></li>\n<li><code>+crcFlags</code> [0..1]: Komposition auf <code>EthTSynCrcFlags</code>.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong><code>EthTSynCrcFlags</code></strong>:</li>\n<li>Konfiguriert die Einbeziehung einzelner Header-Felder in die Prüfsummenberechnung (CRC) für Time-Synchronization-Nachrichten über Ethernet.</li>\n<li><em>Attribute:</em></li>\n<li><code>crcCorrectionField :Boolean</code> [0..1]: Berücksichtigung des Correction-Field in der CRC.</li>\n<li><code>crcDomainNumber :Boolean</code> [0..1]: Berücksichtigung der Domain-Nummer in der CRC.</li>\n<li><code>crcMessageLength :Boolean</code> [0..1]: Berücksichtigung der Nachrichtenlänge in der CRC.</li>\n<li><code>crcPreciseOriginTimestamp :Boolean</code> [0..1]: Berücksichtigung des Precise-Origin-Timestamps in der CRC.</li>\n<li><code>crcSequenceId :Boolean</code> [0..1]: Berücksichtigung der Sequence-ID in der CRC.</li>\n<li><code>crcSourcePortIdentity :Boolean</code> [0..1]: Berücksichtigung der Source-Port-Identity in der CRC.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong><code>«enumeration» EthGlobalTimeMessageFormatEnum</code></strong>:</li>\n<li><code>IEEE802_1AS</code>: Standardkonforme gPTP-Nachrichten gemäß IEEE 802.1AS.</li>\n<li><code>IEEE802_1AS_AUTOSAR</code>: AUTOSAR-spezifisches Subprofil mit erweiterten TLVs und Absicherungsmechanismen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das statische Metamodell definiert die Parameter für folgende Laufzeitabläufe im <code>EthTSyn</code>- und <code>StbM</code>-Stack:</p>\n<ol class=\"fig-list\">\n<li><strong>Nachrichtenvalidierung & Sequence-Tracking:</strong> Bei Wahl von <code>IEEE802_1AS_AUTOSAR</code> wird beim Empfang einer <em>Follow_Up</em>-PDU die geordnete <code>fupDataIDList</code> zur Integritäts- und Sequence-Counter-Prüfung verwendet. Entspricht die berechnete Prüfsumme/Data-ID nicht dem erwarteten Sequenzwert der Liste, wird der Timestamp verworfen.</li>\n<li><strong>Synchronisationsüberwachung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ein Timer überwacht das Intervall empfangener Sync-Frames gegen <code>syncLossTimeout</code>.</li>\n<li>Weicht der rekonstruierte Offset vom Master über <code>syncLossThreshold</code> ab oder läuft der Timeout ab, meldet <code>StbM</code> via <code>Dem</code> / <code>Det</code> einen Sync-Verlust (<code>TIMEOUT</code> / <code>SYNC_LOSS</code>) an die Diagnose und setzt den Time-Base-Status auf <em>UNSYNC</em>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Entprellung:</strong> Zustandsübergänge zwischen synchronisiertem und unsynchronisiertem Status werden über <code>debounceTime</code> zeitlich gefiltert, um Hystereseeffekte im BSW-Status zu unterdrücken.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Architektur- und Stack-Abbildung:</strong> Die Eigenschaften steuern direkt die Module <code>EthTSyn</code> und <code>StbM</code>. Über <code>destinationPhysicalAddress</code> wird festgelegt, ob Unicast- oder Multicast-MACs für gPTP verwendet werden.</li>\n<li><strong>Integritätsschutz:</strong> Über <code>EthTSynCrcFlags</code> lässt sich granular konfigurieren, welche Bestandteile der Ethernet-Zeitsynchronisationsnachrichten durch Prüfsummen abgesichert werden.</li>\n<li><strong>Modellaufteilung und Varianten:</strong> Durch das Stereotyp <code>«atpVariation,atpSplitable»</code> an <code>+globalTimeSubDomain</code> und <code>+globalTimeDomainProperty</code> können Zeitdomäneneigenschaften und Subdomänenverknüpfungen nicht nur variantenabhängig definiert, sondern auch über mehrere ARXML-Dateifragmente hinweg aufgeteilt werden.</li>\n</ul>"}, {"id": "FIG-3eccd868e260e61a", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm (Ausschnitt aus dem AUTOSAR-Metamodell, M2-Ebene, <em>System Template</em> / FIBEX-Mapping).</li>\n<li><strong>Funktionaler Kontext:</strong> Modellierung globaler Zeitdomänen (<em>Global Time Synchronization</em>) für Ethernet im Rahmen des BSW-Stacks (Zusammenwirken von <code>StbM</code> – <em>Synchronized Time-Base Manager</em> und <code>EthTSyn</code> – <em>Time Synchronization over Ethernet</em>).</li>\n<li><strong>Zweck:</strong> Bereitstellung deklarativer Konfigurationsdaten in der Systembeschreibung (ARXML) zur Definition zeitsynchroner Netzwerke über Ethernet (gPTP nach IEEE 802.1AS bzw. AUTOSAR-Erweiterungen), inklusive Domänenhierarchien, Überwachungszeiträumen und absichernder Data-IDs.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>GlobalTimeDomain</code></strong> (Spezialisierung von <code>FibexElement</code> und <code>UploadableDesignElement</code>):</li>\n<li>Repräsentiert eine logische Zeitsynchronisationsdomäne im Gesamtsystem.</li>\n<li><em>Attribute:</em></li>\n<li><code>domainId :PositiveInteger</code> [0..1]: Eindeutige Kennung der Zeitbasis.</li>\n<li><code>debounceTime :TimeValue</code> [0..1]: Mindestabstand zur Ratenbegrenzung bzw. Entprellung von Statusänderungen oder Sync-Meldungen.</li>\n<li><code>syncLossTimeout :TimeValue</code> [0..1]: Zeitspanne ohne gültige Synchronisationsnachricht, nach deren Ablauf der Verlust der Zeitbasis deklariert wird.</li>\n<li><em>Assoziationen / Relationen:</em></li>\n<li><code>+offsetTimeDomain</code> [0..1]: Unidirektionale Selbstassoziation zur Referenzierung einer Basis-Zeitdomäne.</li>\n<li><code>+globalTimeSubDomain</code> [0..*]: Unidirektionale Kaskadierung untergeordneter Zeitdomänen mit Stereotyp <code>«atpVariation,atpSplitable»</code>.</li>\n<li><code>+globalTimeDomainProperty</code> [0..1]: Komposition auf <code>AbstractGlobalTimeDomainProps</code> mit Stereotyp <code>«atpVariation,atpSplitable»</code>.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong><code>AbstractGlobalTimeDomainProps</code></strong> (abstrakte Basisklasse):</li>\n<li>Kapselt busspezifische Eigenschaften einer Zeitdomäne polymorph unterhalb von <code>GlobalTimeDomain</code>.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong><code>EthGlobalTimeDomainProps</code></strong> (Spezialisierung von <code>AbstractGlobalTimeDomainProps</code>):</li>\n<li>Konkrete Eigenschaftsklasse für Ethernet-basierte Zeitdomänen.</li>\n<li><em>Attribute:</em></li>\n<li><code>destinationPhysicalAddress :MacAddressString</code> [0..1]: Physikalische Ziel-MAC-Adresse für Ethernet-Zeitsynchronisationsnachrichten.</li>\n<li><code>fupDataIDList :PositiveInteger</code> [0..16] <code>{ordered}</code>: Geordnete Sequenz von bis zu 16 Data-IDs zur Absicherung von <em>Follow_Up</em>-Nachrichten.</li>\n<li><code>messageCompliance :EthGlobalTimeMessageFormatEnum</code> [0..1]: Selektor für das PTP-Nachrichtenformat.</li>\n<li><code>vlanPriority :PositiveInteger</code> [0..1]: Priority Code Point (PCP nach IEEE 802.1Q) für das VLAN-Tagging.</li>\n<li><em>Assoziationen / Relationen:</em></li>\n<li><code>+crcFlags</code> [0..1]: Komposition auf <code>EthTSynCrcFlags</code>.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong><code>EthTSynCrcFlags</code></strong>:</li>\n<li>Konfiguriert die Einbeziehung einzelner Header-Felder in die Prüfsummenberechnung (CRC) für Time-Synchronization-Nachrichten über Ethernet.</li>\n<li><em>Attribute:</em></li>\n<li><code>crcCorrectionField :Boolean</code> [0..1]: Berücksichtigung des Correction-Field in der CRC.</li>\n<li><code>crcDomainNumber :Boolean</code> [0..1]: Berücksichtigung der Domain-Nummer in der CRC.</li>\n<li><code>crcMessageLength :Boolean</code> [0..1]: Berücksichtigung der Nachrichtenlänge in der CRC.</li>\n<li><code>crcPreciseOriginTimestamp :Boolean</code> [0..1]: Berücksichtigung des Precise-Origin-Timestamps in der CRC.</li>\n<li><code>crcSequenceId :Boolean</code> [0..1]: Berücksichtigung der Sequence-ID in der CRC.</li>\n<li><code>crcSourcePortIdentity :Boolean</code> [0..1]: Berücksichtigung der Source-Port-Identity in der CRC.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong><code>«enumeration» EthGlobalTimeMessageFormatEnum</code></strong>:</li>\n<li><code>IEEE802_1AS</code>: Standardkonforme gPTP-Nachrichten gemäß IEEE 802.1AS.</li>\n<li><code>IEEE802_1AS_AUTOSAR</code>: AUTOSAR-spezifisches Subprofil mit erweiterten TLVs und Absicherungsmechanismen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das statische Metamodell definiert die Parameter für folgende Laufzeitabläufe im <code>EthTSyn</code>- und <code>StbM</code>-Stack:</p>\n<ol class=\"fig-list\">\n<li><strong>Nachrichtenvalidierung & Sequence-Tracking:</strong> Bei Wahl von <code>IEEE802_1AS_AUTOSAR</code> wird beim Empfang einer <em>Follow_Up</em>-PDU die geordnete <code>fupDataIDList</code> zur Integritäts- und Sequence-Counter-Prüfung verwendet. Entspricht die berechnete Prüfsumme/Data-ID nicht dem erwarteten Sequenzwert der Liste, wird der Timestamp verworfen.</li>\n<li><strong>Synchronisationsüberwachung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ein Timer überwacht das Intervall empfangener Sync-Frames gegen <code>syncLossTimeout</code>.</li>\n<li>Weicht der rekonstruierte Offset vom Master über <code>syncLossThreshold</code> ab oder läuft der Timeout ab, meldet <code>StbM</code> via <code>Dem</code> / <code>Det</code> einen Sync-Verlust (<code>TIMEOUT</code> / <code>SYNC_LOSS</code>) an die Diagnose und setzt den Time-Base-Status auf <em>UNSYNC</em>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Entprellung:</strong> Zustandsübergänge zwischen synchronisiertem und unsynchronisiertem Status werden über <code>debounceTime</code> zeitlich gefiltert, um Hystereseeffekte im BSW-Status zu unterdrücken.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Architektur- und Stack-Abbildung:</strong> Die Eigenschaften steuern direkt die Module <code>EthTSyn</code> und <code>StbM</code>. Über <code>destinationPhysicalAddress</code> wird festgelegt, ob Unicast- oder Multicast-MACs für gPTP verwendet werden.</li>\n<li><strong>Integritätsschutz:</strong> Über <code>EthTSynCrcFlags</code> lässt sich granular konfigurieren, welche Bestandteile der Ethernet-Zeitsynchronisationsnachrichten durch Prüfsummen abgesichert werden.</li>\n<li><strong>Modellaufteilung und Varianten:</strong> Durch das Stereotyp <code>«atpVariation,atpSplitable»</code> an <code>+globalTimeSubDomain</code> und <code>+globalTimeDomainProperty</code> können Zeitdomäneneigenschaften und Subdomänenverknüpfungen nicht nur variantenabhängig definiert, sondern auch über mehrere ARXML-Dateifragmente hinweg aufgeteilt werden.</li>\n</ul>"}, {"id": "FIG-461969f432a4bf44", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm (Ausschnitt aus dem AUTOSAR-Metamodell, M2-Ebene, <em>System Template</em> / FIBEX-Mapping).</li>\n<li><strong>Funktionaler Kontext:</strong> Modellierung globaler Zeitdomänen (<em>Global Time Synchronization</em>) für Ethernet im Rahmen des BSW-Stacks (Zusammenwirken von <code>StbM</code> – <em>Synchronized Time-Base Manager</em> und <code>EthTSyn</code> – <em>Time Synchronization over Ethernet</em>).</li>\n<li><strong>Zweck:</strong> Bereitstellung deklarativer Konfigurationsdaten in der Systembeschreibung (ARXML) zur Definition zeitsynchroner Netzwerke über Ethernet (gPTP nach IEEE 802.1AS bzw. AUTOSAR-Erweiterungen), inklusive Domänenhierarchien, Überwachungszeiträumen und absichernder Data-IDs.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>GlobalTimeDomain</code></strong> (Spezialisierung von <code>FibexElement</code> und <code>UploadableDesignElement</code>):</li>\n<li>Repräsentiert eine logische Zeitsynchronisationsdomäne im Gesamtsystem.</li>\n<li><em>Attribute:</em></li>\n<li><code>domainId :PositiveInteger</code> [0..1]: Eindeutige Kennung der Zeitbasis.</li>\n<li><code>debounceTime :TimeValue</code> [0..1]: Mindestabstand zur Ratenbegrenzung bzw. Entprellung von Statusänderungen oder Sync-Meldungen.</li>\n<li><code>icvFreshnessValueId :PositiveInteger</code> [0..1]: Kennung des Frischewerts für Integrity Check Values (ICV) zur Absicherung von Zeitsynchronisationsnachrichten.</li>\n<li><code>maxProgressionMismatchThreshold :TimeValue</code> [0..1]: Schwellenwert für maximal tolerierte Abweichungen des Zeitfortschritts.</li>\n<li><code>syncLossTimeout :TimeValue</code> [0..1]: Zeitspanne ohne gültige Synchronisationsnachricht, nach deren Ablauf der Verlust der Zeitbasis deklariert wird.</li>\n<li><em>Assoziationen / Relationen:</em></li>\n<li><code>+globalTimeSubDomain</code> [0..*]: Unidirektionale Kaskadierung untergeordneter Zeitdomänen mit Stereotyp <code>«atpVariation,atpSplitable»</code>.</li>\n<li><code>+globalTimeDomainProperty</code> [0..1]: Komposition auf <code>AbstractGlobalTimeDomainProps</code> mit Stereotyp <code>«atpVariation,atpSplitable»</code>.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong><code>AbstractGlobalTimeDomainProps</code></strong> (abstrakte Basisklasse):</li>\n<li>Kapselt busspezifische Eigenschaften einer Zeitdomäne polymorph unterhalb von <code>GlobalTimeDomain</code>.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong><code>EthGlobalTimeDomainProps</code></strong> (Spezialisierung von <code>AbstractGlobalTimeDomainProps</code>):</li>\n<li>Konkrete Eigenschaftsklasse für Ethernet-basierte Zeitdomänen.</li>\n<li><em>Attribute:</em></li>\n<li><code>destinationPhysicalAddress :MacAddressString</code> [0..1]: Physikalische Ziel-MAC-Adresse für Ethernet-Zeitsynchronisationsnachrichten.</li>\n<li><code>fupDataIDList :PositiveInteger</code> [0..16] <code>{ordered}</code>: Geordnete Sequenz von bis zu 16 Data-IDs zur Absicherung von <em>Follow_Up</em>-Nachrichten.</li>\n<li><code>messageCompliance :EthGlobalTimeMessageFormatEnum</code> [0..1]: Selektor für das PTP-Nachrichtenformat.</li>\n<li><code>vlanPriority :PositiveInteger</code> [0..1]: Priority Code Point (PCP nach IEEE 802.1Q) für das VLAN-Tagging.</li>\n<li><em>Assoziationen / Relationen:</em></li>\n<li><code>+crcFlags</code> [0..1]: Komposition auf <code>EthTSynCrcFlags</code>.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong><code>EthTSynCrcFlags</code></strong>:</li>\n<li>Konfiguriert die Einbeziehung einzelner Header-Felder in die Prüfsummenberechnung (CRC) für Time-Synchronization-Nachrichten über Ethernet.</li>\n<li><em>Attribute:</em></li>\n<li><code>crcCorrectionField :Boolean</code> [0..1]: Berücksichtigung des Correction-Field in der CRC.</li>\n<li><code>crcDomainNumber :Boolean</code> [0..1]: Berücksichtigung der Domain-Nummer in der CRC.</li>\n<li><code>crcMessageLength :Boolean</code> [0..1]: Berücksichtigung der Nachrichtenlänge in der CRC.</li>\n<li><code>crcPreciseOriginTimestamp :Boolean</code> [0..1]: Berücksichtigung des Precise-Origin-Timestamps in der CRC.</li>\n<li><code>crcSequenceId :Boolean</code> [0..1]: Berücksichtigung der Sequence-ID in der CRC.</li>\n<li><code>crcSourcePortIdentity :Boolean</code> [0..1]: Berücksichtigung der Source-Port-Identity in der CRC.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong><code>«enumeration» EthGlobalTimeMessageFormatEnum</code></strong>:</li>\n<li><em>literals:</em></li>\n<li><code>IEEE802_1AS</code>: Standardkonforme gPTP-Nachrichten gemäß IEEE 802.1AS.</li>\n<li><code>IEEE802_1AS_AUTOSAR</code>: AUTOSAR-spezifisches Subprofil mit erweiterten TLVs und Absicherungsmechanismen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das statische Metamodell definiert die Parameter für folgende Laufzeitabläufe im <code>EthTSyn</code>- und <code>StbM</code>-Stack:</p>\n<ol class=\"fig-list\">\n<li><strong>Nachrichtenvalidierung & Sequence-Tracking:</strong> Bei Wahl von <code>IEEE802_1AS_AUTOSAR</code> wird beim Empfang einer <em>Follow_Up</em>-PDU die geordnete <code>fupDataIDList</code> zur Integritäts- und Sequence-Counter-Prüfung verwendet. Entspricht die berechnete Prüfsumme/Data-ID nicht dem erwarteten Sequenzwert der Liste, wird der Timestamp verworfen.</li>\n<li><strong>Synchronisationsüberwachung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ein Timer überwacht das Intervall empfangener Sync-Frames gegen <code>syncLossTimeout</code>.</li>\n<li>Weicht der rekonstruierte Offset vom Master über <code>syncLossThreshold</code> ab oder läuft der Timeout ab, meldet <code>StbM</code> via <code>Dem</code> / <code>Det</code> einen Sync-Verlust (<code>TIMEOUT</code> / <code>SYNC_LOSS</code>) an die Diagnose und setzt den Time-Base-Status auf <em>UNSYNC</em>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Entprellung:</strong> Zustandsübergänge zwischen synchronisiertem und unsynchronisiertem Status werden über <code>debounceTime</code> zeitlich gefiltert, um Hystereseeffekte im BSW-Status zu unterdrücken.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Sicherheits- und Plausibilitätsprüfungen:</strong> <code>icvFreshnessValueId</code> ermöglicht die Integration kryptografischer Frische-Mechanismen zur Abwehr von Replay-Angriffen über ICVs. <code>maxProgressionMismatchThreshold</code> definiert eine obere Schranke für Monotonie- und Driftprüfungen im Zeitverlauf.</li>\n<li><strong>Konfigurationshinweise:</strong> Durch den Wegfall von <code>offsetTimeDomain</code> werden Offset-Beziehungen zwischen Zeitdomänen nicht mehr über dieses Metamodellelement an der <code>GlobalTimeDomain</code> deklariert.</li>\n</ul>"}, {"id": "FIG-0f17ec9601f07439", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm (Ausschnitt aus dem AUTOSAR-Metamodell, M2-Ebene, <em>System Template</em> / FIBEX-Mapping).</li>\n<li><strong>Funktionaler Kontext:</strong> Modellierung globaler Zeitdomänen (<em>Global Time Synchronization</em>) für Ethernet im Rahmen des BSW-Stacks (Zusammenwirken von <code>StbM</code> – <em>Synchronized Time-Base Manager</em> und <code>EthTSyn</code> – <em>Time Synchronization over Ethernet</em>).</li>\n<li><strong>Zweck:</strong> Bereitstellung deklarativer Konfigurationsdaten in der Systembeschreibung (ARXML) zur Definition zeitsynchroner Netzwerke über Ethernet (gPTP nach IEEE 802.1AS bzw. AUTOSAR-Erweiterungen), inklusive Domänenhierarchien, Überwachungszeiträumen und absichernder Data-IDs.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>GlobalTimeDomain</code></strong> (Spezialisierung von <code>FibexElement</code> und <code>UploadableDesignElement</code>):</li>\n<li>Repräsentiert eine logische Zeitsynchronisationsdomäne im Gesamtsystem.</li>\n<li><em>Attribute:</em></li>\n<li><code>«atpVariation» domainId :PositiveInteger</code> [0..1]: Eindeutige Kennung der Zeitbasis, variantenfähig.</li>\n<li><code>debounceTime :TimeValue</code> [0..1]: Mindestabstand zur Ratenbegrenzung bzw. Entprellung von Statusänderungen oder Sync-Meldungen.</li>\n<li><code>icvFreshnessValueId :PositiveInteger</code> [0..1]: Kennung des Frischewerts für Integrity Check Values (ICV).</li>\n<li><code>maxProgressionMismatchThreshold :TimeValue</code> [0..1]: Schwellenwert für maximal tolerierte Abweichungen des Zeitfortschritts.</li>\n<li><code>syncLossTimeout :TimeValue</code> [0..1]: Zeitspanne ohne gültige Synchronisationsnachricht, nach deren Ablauf der Verlust der Zeitbasis deklariert wird.</li>\n<li><em>Assoziationen / Relationen:</em></li>\n<li><code>+globalTimeSubDomain</code> [0..*]: Unidirektionale Kaskadierung untergeordneter Zeitdomänen mit Stereotyp <code>«atpVariation,atpSplitable»</code>.</li>\n<li><code>+globalTimeDomainProperty</code> [0..1]: Komposition auf <code>AbstractGlobalTimeDomainProps</code> mit Stereotyp <code>«atpVariation,atpSplitable»</code>.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong><code>AbstractGlobalTimeDomainProps</code></strong> (abstrakte Basisklasse):</li>\n<li>Kapselt busspezifische Eigenschaften einer Zeitdomäne polymorph unterhalb von <code>GlobalTimeDomain</code>.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong><code>EthGlobalTimeDomainProps</code></strong> (Spezialisierung von <code>AbstractGlobalTimeDomainProps</code>):</li>\n<li>Konkrete Eigenschaftsklasse für Ethernet-basierte Zeitdomänen.</li>\n<li><em>Attribute:</em></li>\n<li><code>destinationPhysicalAddress :MacAddressString</code> [0..1]: Physikalische Ziel-MAC-Adresse für Ethernet-Zeitsynchronisationsnachrichten.</li>\n<li><code>fupDataIDList :PositiveInteger</code> [0..16] <code>{ordered}</code>: Geordnete Sequenz von bis zu 16 Data-IDs zur Absicherung von <em>Follow_Up</em>-Nachrichten.</li>\n<li><code>messageCompliance :EthGlobalTimeMessageFormatEnum</code> [0..1]: Selektor für das PTP-Nachrichtenformat.</li>\n<li><code>vlanPriority :PositiveInteger</code> [0..1]: Priority Code Point (PCP nach IEEE 802.1Q) für das VLAN-Tagging.</li>\n<li><em>Assoziationen / Relationen:</em></li>\n<li><code>+crcFlags</code> [0..1]: Komposition auf <code>EthTSynCrcFlags</code>.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong><code>EthTSynCrcFlags</code></strong>:</li>\n<li>Konfiguriert die Einbeziehung einzelner Header-Felder in die Prüfsummenberechnung (CRC) für Time-Synchronization-Nachrichten über Ethernet.</li>\n<li><em>Attribute:</em></li>\n<li><code>crcCorrectionField :Boolean</code> [0..1]: Berücksichtigung des Correction-Field in der CRC.</li>\n<li><code>crcDomainNumber :Boolean</code> [0..1]: Berücksichtigung der Domain-Nummer in der CRC.</li>\n<li><code>crcMessageLength :Boolean</code> [0..1]: Berücksichtigung der Nachrichtenlänge in der CRC.</li>\n<li><code>crcPreciseOriginTimestamp :Boolean</code> [0..1]: Berücksichtigung des Precise-Origin-Timestamps in der CRC.</li>\n<li><code>crcSequenceId :Boolean</code> [0..1]: Berücksichtigung der Sequence-ID in der CRC.</li>\n<li><code>crcSourcePortIdentity :Boolean</code> [0..1]: Berücksichtigung der Source-Port-Identity in der CRC.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong><code>«enumeration» EthGlobalTimeMessageFormatEnum</code></strong>:</li>\n<li><em>literals:</em></li>\n<li><code>IEEE802_1AS</code>: Standardkonforme gPTP-Nachrichten gemäß IEEE 802.1AS.</li>\n<li><code>IEEE802_1AS_AUTOSAR</code>: AUTOSAR-spezifisches Subprofil mit erweiterten TLVs und Absicherungsmechanismen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das statische Metamodell definiert die Parameter für folgende Laufzeitabläufe im <code>EthTSyn</code>- und <code>StbM</code>-Stack:</p>\n<ol class=\"fig-list\">\n<li><strong>Nachrichtenvalidierung & Sequence-Tracking:</strong> Bei Wahl von <code>IEEE802_1AS_AUTOSAR</code> wird beim Empfang einer <em>Follow_Up</em>-PDU die geordnete <code>fupDataIDList</code> zur Integritäts- und Sequence-Counter-Prüfung verwendet. Entspricht die berechnete Prüfsumme/Data-ID nicht dem erwarteten Sequenzwert der Liste, wird der Timestamp verworfen.</li>\n<li><strong>Synchronisationsüberwachung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ein Timer überwacht das Intervall empfangener Sync-Frames gegen <code>syncLossTimeout</code>.</li>\n<li>Weicht der rekonstruierte Offset vom Master über <code>syncLossThreshold</code> ab oder läuft der Timeout ab, meldet <code>StbM</code> via <code>Dem</code> / <code>Det</code> einen Sync-Verlust (<code>TIMEOUT</code> / <code>SYNC_LOSS</code>) an die Diagnose und setzt den Time-Base-Status auf <em>UNSYNC</em>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Entprellung:</strong> Zustandsübergänge zwischen synchronisiertem und unsynchronisiertem Status werden über <code>debounceTime</code> zeitlich gefiltert, um Hystereseeffekte im BSW-Status zu unterdrücken.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Sicherheits- und Plausibilitätsprüfungen:</strong> <code>icvFreshnessValueId</code> ermöglicht die Integration kryptografischer Frische-Mechanismen zur Abwehr von Replay-Angriffen über ICVs. <code>maxProgressionMismatchThreshold</code> definiert eine obere Schranke für Monotonie- und Driftprüfungen im Zeitverlauf.</li>\n<li><strong>Variantenbildung der Domain-ID:</strong> Durch die Zuordnung von <code>«atpVariation»</code> direkt an <code>domainId</code> kann die Domain-Identifikationsnummer systemspezifisch über System-Konfigurationsvarianten und Bindungszeitpunkte variiert werden.</li>\n</ul>"}], "trans": [{"from": "FIG-a31ca4c18bec47b6", "to": "FIG-cf83a50615172ed9", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>GlobalTimeDomain</code>: Attribut <code>syncLossThreshold</code> entfällt.</li>\n<li><code>EthGlobalTimeDomainProps</code>: Attribut <code>destinationPhysicalAddress :MacAddressString [0..1]</code> neu eingefügt.</li>\n<li>Klasse <code>EthTSynCrcFlags</code>: neu modelliert mit den Attributen <code>crcCorrectionField :Boolean [0..1]</code>, <code>crcDomainNumber :Boolean [0..1]</code>, <code>crcMessageLength :Boolean [0..1]</code>, <code>crcPreciseOriginTimestamp :Boolean [0..1]</code>, <code>crcSequenceId :Boolean [0..1]</code> und <code>crcSourcePortIdentity :Boolean [0..1]</code>.</li>\n<li>Assoziation <code>+crcFlags</code>: neue Komposition von <code>EthGlobalTimeDomainProps</code> auf <code>EthTSynCrcFlags</code> mit Kardinalität <code>0..1</code>.</li>\n<li>Rolle <code>+subDomain</code>: umbenannt zu <code>+globalTimeSubDomain</code> und mit Stereotyp <code>«atpVariation»</code> versehen.</li>\n<li>Rolle <code>+globalTimeDomainProps</code>: umbenannt zu <code>+globalTimeDomainProperty</code> und mit Stereotyp <code>«atpVariation»</code> versehen.</li>\n</ul>"}, {"from": "FIG-cf83a50615172ed9", "to": "FIG-bae6585e530974b4", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-bae6585e530974b4", "to": "FIG-b1175ffbdbe95c07", "fr": "R20-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Rolle <code>+globalTimeSubDomain</code>: Stereotyp von <code>«atpVariation»</code> erweitert zu <code>«atpVariation,atpSplitable»</code>.</li>\n<li>Rolle <code>+globalTimeDomainProperty</code>: Stereotyp von <code>«atpVariation»</code> erweitert zu <code>«atpVariation,atpSplitable»</code>.</li>\n</ul>"}, {"from": "FIG-b1175ffbdbe95c07", "to": "FIG-3eccd868e260e61a", "fr": "R22-11", "tr": "R23-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>GlobalTimeDomain</code>: Generalisierung zusätzlich um <code>UploadableDesignElement</code> erweitert; Paketpräfix <code>GlobalTime::</code> am Klassennamen entfallen.</li>\n<li><code>GlobalTimeDomain.domainId</code>: Multiplizität von obligatorisch [1..1] auf optional <code>[0..1]</code> geändert.</li>\n<li><code>AbstractGlobalTimeDomainProps</code>: Paketpräfix <code>GlobalTime::</code> am Klassennamen entfallen.</li>\n<li><code>EthGlobalTimeDomainProps.messageCompliance</code>: Multiplizität von obligatorisch [1..1] auf optional <code>[0..1]</code> geändert.</li>\n</ul>"}, {"from": "FIG-3eccd868e260e61a", "to": "FIG-461969f432a4bf44", "fr": "R23-11", "tr": "R24-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>GlobalTimeDomain</code>: Selbstassoziation <code>+offsetTimeDomain 0..1</code> entfällt.</li>\n<li><code>GlobalTimeDomain</code>: Attribute <code>icvFreshnessValueId :PositiveInteger [0..1]</code> und <code>maxProgressionMismatchThreshold :TimeValue [0..1]</code> neu eingefügt.</li>\n<li><code>EthGlobalTimeMessageFormatEnum</code>: Abschnittskopf <code>literals</code> über den Enumerationswerten ergänzt.</li>\n</ul>"}, {"from": "FIG-461969f432a4bf44", "to": "FIG-0f17ec9601f07439", "fr": "R24-11", "tr": "R25-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>GlobalTimeDomain.domainId</code>: mit Stereotyp <code>«atpVariation»</code> versehen.</li>\n</ul>"}]};
